import type { WashEligibleFn } from "./wash-eligibility";
import { washWindowClearsAtSecs } from "./wash-window";
export interface ExecutorLeg { id: string; inMint: string | null; outMint: string | null; harvestLots: unknown }

export interface HarvestInput {
    assetId: string;
    lotId: string;
    lossUsd: number;
    stOrLt: "st" | "lt";
    replacementAssetId?: string | null;
    washWindowUntil?: number | null;
}

function assetPlaceholder(leg: ExecutorLeg): string {
    if (leg.inMint?.startsWith("asset:"))
        return leg.inMint;
    if (leg.outMint?.startsWith("asset:"))
        return leg.outMint;
    throw new Error(`leg ${leg.id}: no asset mint placeholder on either side`);
}

export function buildHarvestInputs(leg: ExecutorLeg, actualUsdcOut: number | null, filledAtSecs: number, washEligible: WashEligibleFn): HarvestInput[] {
    const raw = leg.harvestLots;
    if (!Array.isArray(raw) || raw.length === 0)
        return [];
    if (actualUsdcOut == null || !(actualUsdcOut > 0))
        return [];
    const lots = raw as {
        lotId: string;
        qty: number;
        basisPerUnitUsd: number;
        stOrLt: "st" | "lt";
    }[];
    const assetId = assetPlaceholder(leg).slice("asset:".length);
    const totalQty = lots.reduce((s, l) => s + (l.qty ?? 0), 0);
    if (!(totalQty > 0))
        return [];
    const proceedsPerUnit = actualUsdcOut / totalQty;
    return lots
        .map((l) => ({ l, lossUsd: (l.qty ?? 0) * (proceedsPerUnit - (l.basisPerUnitUsd ?? 0)) }))
        .filter((x) => x.l.lotId && x.lossUsd < 0)
        .map((x) => ({
        assetId,
        lotId: x.l.lotId,
        lossUsd: x.lossUsd,
        stOrLt: x.l.stOrLt,
        washWindowUntil: washEligible(assetId)
            ? washWindowClearsAtSecs(filledAtSecs)
            : null,
    }));
}
